package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.SortOrder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for DefaultKeyedValues.removeValue(Comparable key).
 */
public class DefaultKeyedValues_removeValue_TriageGen0Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    /**
     * Tests that removing a key that does not exist throws UnknownKeyException.
     * This covers the branch where index < 1.
     */
    @Test(expected = UnknownKeyException.class)
    public void testRemoveValue_KeyNotFoundThrowsException() {
        keyedValues.addValue("A", 1.0);
        keyedValues.removeValue("B");
    }

    /**
     * Tests that removing a key from an empty collection throws UnknownKeyException.
     * This covers the branch where index < 1.
     */
    @Test(expected = UnknownKeyException.class)
    public void testRemoveValue_EmptyCollectionThrowsException() {
        keyedValues.removeValue("A");
    }

    /**
     * Tests that removing an existing key successfully removes the item.
     * This covers the branch where index >= 1.
     */
    @Test
    public void testRemoveValue_ExistingKeyRemovesSuccessfully() {
        String key1 = "A";
        String key2 = "B";
        keyedValues.addValue(key1, 10.0);
        keyedValues.addValue(key2, 20.0);

        assertEquals(2, keyedValues.getItemCount());

        // Execute removal
        keyedValues.removeValue(key1);

        // Verify state
        assertEquals(1, keyedValues.getItemCount());
        assertEquals(key2, keyedValues.getKey(1));
        assertNull(keyedValues.getValue(key1));
    }

    /**
     * Tests that removing the last element works correctly.
     */
    @Test
    public void testRemoveValue_LastElementRemovesSuccessfully() {
        String key1 = "A";
        String key2 = "B";
        keyedValues.addValue(key1, 10.0);
        keyedValues.addValue(key2, 20.0);

        keyedValues.removeValue(key2);

        assertEquals(1, keyedValues.getItemCount());
        assertEquals(key1, keyedValues.getKey(1));
    }
}
